-- SECURITY DEFINER; API roles that may call it: service_role
CREATE OR REPLACE FUNCTION public.log_application_approved()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if old.status = 'pending' and new.status = 'active' then
    insert into public.application_decisions (creator_id, creator_name, email, decision, decided_by)
    values (new.id, new.name, (select email from auth.users where id = new.id), 'approved', auth.uid());
  end if;
  return new;
end $function$;
